CREATE TABLE IF NOT EXISTS users(id SERIAL PRIMARY KEY,full_name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,phone TEXT,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('patient','doctor','admin','receptionist')),active BOOLEAN DEFAULT true,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS patients(id SERIAL PRIMARY KEY,user_id INT UNIQUE REFERENCES users(id),date_of_birth DATE,gender TEXT,blood_group TEXT,address TEXT,emergency_contact TEXT,allergies TEXT);
CREATE TABLE IF NOT EXISTS departments(id SERIAL PRIMARY KEY,name TEXT UNIQUE NOT NULL,description TEXT,location TEXT,contact TEXT,active BOOLEAN DEFAULT true);
CREATE TABLE IF NOT EXISTS doctors(id SERIAL PRIMARY KEY,user_id INT UNIQUE REFERENCES users(id),department_id INT REFERENCES departments(id),qualification TEXT,specialization TEXT,experience_years INT,consultation_fee NUMERIC(10,2),availability TEXT DEFAULT 'Available',bio TEXT,image TEXT,active BOOLEAN DEFAULT true);
CREATE OR REPLACE VIEW doctor_directory AS SELECT d.id,d.department_id,u.full_name,d.qualification,d.specialization,d.experience_years,d.consultation_fee,d.availability,d.bio,d.image,dep.name department FROM doctors d JOIN users u ON u.id=d.user_id JOIN departments dep ON dep.id=d.department_id WHERE d.active=true;
CREATE TABLE IF NOT EXISTS doctor_schedules(id SERIAL PRIMARY KEY,doctor_id INT REFERENCES doctors(id),day_of_week INT,start_time TIME,end_time TIME,available BOOLEAN DEFAULT true,UNIQUE(doctor_id,day_of_week));
CREATE TABLE IF NOT EXISTS appointments(id SERIAL PRIMARY KEY,appointment_code TEXT UNIQUE NOT NULL,patient_id INT REFERENCES patients(id),doctor_id INT REFERENCES doctors(id),department_id INT REFERENCES departments(id),appointment_date DATE NOT NULL,appointment_time TIME NOT NULL,appointment_type TEXT CHECK(appointment_type IN('in_person','video')),reason TEXT,notes TEXT,status TEXT DEFAULT 'pending' CHECK(status IN('pending','confirmed','completed','cancelled','no_show')),created_at TIMESTAMPTZ DEFAULT now(),UNIQUE(doctor_id,appointment_date,appointment_time));
CREATE TABLE IF NOT EXISTS medical_records(id SERIAL PRIMARY KEY,patient_id INT REFERENCES patients(id),doctor_id INT REFERENCES doctors(id),appointment_id INT REFERENCES appointments(id),visit_date DATE DEFAULT current_date,symptoms TEXT,diagnosis TEXT,treatment TEXT,notes TEXT,follow_up_date DATE);
CREATE TABLE IF NOT EXISTS prescriptions(id SERIAL PRIMARY KEY,patient_id INT REFERENCES patients(id),doctor_id INT REFERENCES doctors(id),medical_record_id INT REFERENCES medical_records(id),created_at TIMESTAMPTZ DEFAULT now()); CREATE TABLE IF NOT EXISTS prescription_items(id SERIAL PRIMARY KEY,prescription_id INT REFERENCES prescriptions(id) ON DELETE CASCADE,medicine TEXT,dosage TEXT,frequency TEXT,duration TEXT,instructions TEXT);
CREATE TABLE IF NOT EXISTS bills(id SERIAL PRIMARY KEY,patient_id INT REFERENCES patients(id),consultation NUMERIC DEFAULT 0,laboratory NUMERIC DEFAULT 0,medicines NUMERIC DEFAULT 0,room_charges NUMERIC DEFAULT 0,other_charges NUMERIC DEFAULT 0,discount NUMERIC DEFAULT 0,tax NUMERIC DEFAULT 0,total NUMERIC DEFAULT 0,status TEXT DEFAULT 'pending',created_at TIMESTAMPTZ DEFAULT now()); CREATE TABLE IF NOT EXISTS payments(id SERIAL PRIMARY KEY,bill_id INT REFERENCES bills(id),amount NUMERIC,payment_method TEXT,transaction_id TEXT,payment_status TEXT,payment_date TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS reviews(id SERIAL PRIMARY KEY,doctor_id INT REFERENCES doctors(id),patient_id INT REFERENCES users(id),rating INT CHECK(rating BETWEEN 1 AND 5),comment TEXT,created_at TIMESTAMPTZ DEFAULT now()); CREATE TABLE IF NOT EXISTS notifications(id SERIAL PRIMARY KEY,user_id INT REFERENCES users(id),message TEXT,type TEXT,read BOOLEAN DEFAULT false,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS hospital_content(key TEXT PRIMARY KEY,value TEXT); CREATE TABLE IF NOT EXISTS leadership(id SERIAL PRIMARY KEY,name TEXT NOT NULL,designation TEXT,image TEXT,description TEXT,display_order INT,status BOOLEAN DEFAULT true); CREATE TABLE IF NOT EXISTS partners(id SERIAL PRIMARY KEY,name TEXT NOT NULL,image TEXT,description TEXT,display_order INT,status BOOLEAN DEFAULT true);
